   241	void LibRaw::parse_riff()
   242	{
   243	  unsigned i, size, end;
   244	  char tag[4], date[64], month[64];
   245	  static const char mon[12][4] = {"Jan", "Feb", "Mar", "Apr", "May", "Jun",
   246	                                  "Jul", "Aug", "Sep", "Oct", "Nov", "Dec"};
   247	  struct tm t;
   248	
   249	  order = 0x4949;
   250	  fread(tag, 4, 1, ifp);
   251	  size = get4();
   252	  end = ftell(ifp) + size;
   253	  if (!memcmp(tag, "RIFF", 4) || !memcmp(tag, "LIST", 4))
   254	  {
   255	    int maxloop = 1000;
   256	    get4();
   257	    while (ftell(ifp) + 7 < end && !feof(ifp) && maxloop--)
   258	      parse_riff();
   259	  }
   260	  else if (!memcmp(tag, "nctg", 4))
   261	  {
   262	    while (ftell(ifp) + 7 < end)
   263	    {
   264	      i = get2();
   265	      size = get2();
   266	      if ((i + 1) >> 1 == 10 && size == 20)
   267	        get_timestamp(0);
   268	      else
   269	        fseek(ifp, size, SEEK_CUR);
   270	    }
   271	  }
   272	  else if (!memcmp(tag, "IDIT", 4) && size < 64)
   273	  {
   274	    fread(date, 64, 1, ifp);
   275	    date[size] = 0;
   276	    memset(&t, 0, sizeof t);
   277	    if (sscanf(date, "%*s %s %d %d:%d:%d %d", month, &t.tm_mday, &t.tm_hour,
   278	               &t.tm_min, &t.tm_sec, &t.tm_year) == 6)
   279	    {
   280	      for (i = 0; i < 12 && strcasecmp(mon[i], month); i++)
   281	        ;
   282	      t.tm_mon = i;
   283	      t.tm_year -= 1900;
   284	      if (mktime(&t) > 0)
   285	        timestamp = mktime(&t);
   286	    }
   287	  }
   288	  else
   289	    fseek(ifp, size, SEEK_CUR);
   290	}
