   435	int LibRaw::parse_jpeg(int offset)
   436	{
   437	  int len, save, hlen, mark;
   438	  fseek(ifp, offset, SEEK_SET);
   439	  if (fgetc(ifp) != 0xff || fgetc(ifp) != 0xd8)
   440	    return 0;
   441	
   442	  while (fgetc(ifp) == 0xff && (mark = fgetc(ifp)) != 0xda)
   443	  {
   444	    order = 0x4d4d;
   445	    len = get2() - 2;
   446	    save = ftell(ifp);
   447	    if (mark == 0xc0 || mark == 0xc3 || mark == 0xc9)
   448	    {
   449	      fgetc(ifp);
   450	      raw_height = get2();
   451	      raw_width = get2();
   452	    }
   453	    order = get2();
   454	    hlen = get4();
   455	    if (get4() == 0x48454150 && (save + hlen) >= 0 &&
   456	        (save + hlen) <= ifp->size()) /* "HEAP" */
   457	    {
   458	      parse_ciff(save + hlen, len - hlen, 0);
   459	    }
   460	    if (parse_tiff(save + 6))
   461	      apply_tiff();
   462	    fseek(ifp, save + len, SEEK_SET);
   463	  }
   464	  return 1;
   465	}
